#ifndef TAGSDK_INC_TAGNVITEM_H_
#define TAGSDK_INC_TAGNVITEM_H_

#include "TagConfig.h"

/**
 * @brief Contains a enumeration values for types of Tag's NV item
 */
typedef enum {
    TAG_NV_INVALID_ITEM = -1,

    /* For RW Items */
    TAG_NV_RW_ITEM_FIRST = 0,
#if defined(TAG_ACCESSORY_OPTION_BUTTON_ACTION) && (TAG_ACCESSORY_OPTION_BUTTON_ACTION == 1)
    TAG_NV_BUTTON_PUSH_ACTION = TAG_NV_RW_ITEM_FIRST,
    TAG_NV_BUTTON_HOLD_ACTION,
    TAG_NV_E2E_ENCRYPTION,
#else
    TAG_NV_E2E_ENCRYPTION = TAG_NV_RW_ITEM_FIRST,
#endif // TAG_ACCESSORY_OPTION_BUTTON_ACTION
    TAG_NV_E2E_ENCRYPTION_KEY_AES,
    TAG_NV_PREMATURE_OFFLINE_TIMEOUT,
    TAG_NV_OVERMATURE_OFFLINE_TIMEOUT,
    TAG_NV_RINGTONE_NAME,
    TAG_NV_RINGTONE_DATA,
    TAG_NV_MAX_ALLOWED_BLE_CONNECTION,
    TAG_NV_MASTER_SECRET_AES,
    TAG_NV_SOUND_VOLUME,
    TAG_NV_REGION,
    TAG_NV_ONBOARDED,
    TAG_NV_OTA_MODE_ENABLED,
    TAG_NV_PRIVACY_ID_SEED,
    TAG_NV_PRIVACY_ID_IV,
    TAG_NV_BOOT_REASON,
    TAG_NV_SAVED_RTC,
    TAG_NV_BLE_IRK,
    TAG_NV_RINGTONE_DATA_SIZE,
    TAG_NV_NUMBER_OF_PRIVACY_ID,
    TAG_NV_ACTIVITY_MODE,
#ifdef TAG_CONFIG_USE_UWB_CHARACTERISTICS
    TAG_NV_UWB_GROUP_DELAY_CALIBRATED,
#endif
#ifdef TAG_CONFIG_USE_DEBUG_CHARACTERISTICS
    TAG_NV_FLASH_LOGGING_BLOCK_POS,
#endif /* TAG_CONFIG_USE_DEBUG_CHARACTERISTICS */
    TAG_NV_BATTERY_LEVEL,
    TAG_NV_TX_POWER,
    TAG_NV_RW_ITEM_LAST = TAG_NV_TX_POWER,

    TAG_NV_RW_ITEM_ALL = 99,

    /* For Read Only (Factory) */
    TAG_NV_RO_ITEM_FIRST = 100,
    TAG_NV_MODEL_NAME = TAG_NV_RO_ITEM_FIRST,
    TAG_NV_VENDOR_ID,
    TAG_NV_MANUFACTURER_ID,
    TAG_NV_MANUFACTURER_NAME,
    TAG_NV_SETUP_ID,
    TAG_NV_SERIAL_NUMBER,
    TAG_NV_PRIVATE_KEY_CURVED,

#ifdef TAG_CONFIG_USE_UWB_CHARACTERISTICS
    TAG_NV_UWB_CH5_TXPWR_INDEX,
    TAG_NV_UWB_TXPWR_INDEX,
    TAG_NV_UWB_TXPWR_PEAK_DELTA,
    TAG_NV_UWB_TXPWR_GREF_INDEX,
    TAG_NV_UWB_FREQ_OFFSET_SIGN,
    TAG_NV_UWB_FREQ_OFFSET_VALUE,
    TAG_NV_RO_ITEM_LAST = TAG_NV_UWB_FREQ_OFFSET_VALUE,
#else
    TAG_NV_RO_ITEM_LAST = TAG_NV_PRIVATE_KEY_CURVED,
#endif
    TAG_NV_RO_ITEM_ALL = 199,

    /* Vendor specific data */
    TAG_NV_VENDOR_ITEM_FIRST = 200,
    TAG_NV_VENDOR_DATA_A_FIXED_SZ = TAG_NV_VENDOR_ITEM_FIRST,
    TAG_NV_VENDOR_DATA_B_FIXED_SZ,

    TAG_NV_VENDOR_ITEM_LAST = TAG_NV_VENDOR_DATA_B_FIXED_SZ,
    TAG_NV_VENDOR_ITEM_ALL = 299,
} TagNVItem_t;

#define TAG_NV_RW_ITEM_CNT_MAX(_YOUR_NV_RW_LAST)    (_YOUR_NV_RW_LAST - TAG_NV_RW_ITEM_FIRST + 1)
#define TAG_NV_RW_ITEM_IDX(_TAG_NV_RW_ITEM)         (_TAG_NV_RW_ITEM - TAG_NV_RW_ITEM_FIRST)

#define TAG_NV_RO_ITEM_CNT_MAX(_YOUR_NV_RO_LAST)    (_YOUR_NV_RO_LAST - TAG_NV_RO_ITEM_FIRST + 1)
#define TAG_NV_RO_ITEM_IDX(_TAG_NV_RO_ITEM)         (_TAG_NV_RO_ITEM - TAG_NV_RO_ITEM_FIRST)

#define TAG_NV_VENDOR_ITEM_CNT_MAX(_YOUR_NV_VENDOR_LAST)    (_YOUR_NV_VENDOR_LAST - TAG_NV_VENDOR_ITEM_FIRST + 1)
#define TAG_NV_VENDOR_ITEM_IDX(_TAG_NV_VENDOR_ITEM)         (_TAG_NV_VENDOR_ITEM - TAG_NV_VENDOR_ITEM_FIRST)

#endif /* TAGSDK_INC_TAGNVITEM_H_ */
